  assign Delay019_reg_next_re[0] = Delay0_out1_re_18;
  assign Delay019_reg_next_im[0] = Delay0_out1_im_18;
  assign Delay019_reg_next_re[1] = Delay019_reg_re[0];
  assign Delay019_reg_next_im[1] = Delay019_reg_im[0];

  assign coeffphaseSig1_19 = 16'sb0000000001100000;

  assign coeffphaseSig2_19 = 16'sb1111111111110101;

  assign prodMux10_out1_19 = (HDL_Counter_out1 == 1'b0 ? coeffphaseSig1_19 :
              coeffphaseSig2_19);

  assign Product108_mul_temp = Delay0_out1_re_19 * prodMux10_out1_19;
  assign Product10_Re_20 = Product108_mul_temp[31:16];

  assign Product109_mul_temp = Delay0_out1_im_19 * prodMux10_out1_19;
  assign Product10_Im_20 = Product109_mul_temp[31:16];

  assign addtree_re_18 = addtree_re_17 + Product10_Re_20;
  assign addtree_im_18 = addtree_im_17 + Product10_Im_20;

  assign addtree_re_19 = addtree_re_14 + addtree_re_18;
  assign addtree_im_19 = addtree_im_14 + addtree_im_18;

  assign ConstantOneS = 1'b1;

  assign Compare_To_Constant_out1s2_1 = HDL_Counter_out1 == ConstantOneS;

  assign switch_compare_1_1 = Compare_To_Constant_out1s2_1 > 1'b0;

  assign Constant1_out1_re = 16'sb0000000000000000;
  assign Constant1_out1_im = 16'sb0000000000000000;

  always @(posedge clk or posedge reset)
    begin : Delay020_process
      if (reset == 1'b1) begin
        Delay0_out1_re_20 <= 16'sb0000000000000000;
        Delay0_out1_im_20 <= 16'sb0000000000000000;
      end
      else begin
        if (enb_1_3_0) begin
          Delay0_out1_re_20 <= AddAfterFeedbackS_re;
          Delay0_out1_im_20 <= AddAfterFeedbackS_im;
        end
      end
    end

  assign Switch_out1_re = (switch_compare_1_1 == 1'b0 ? Delay0_out1_re_20 :
              Constant1_out1_re);
  assign Switch_out1_im = (switch_compare_1_1 == 1'b0 ? Delay0_out1_im_20 :
              Constant1_out1_im);

  assign AddAfterFeedbackS_re = addtree_re_19 + Switch_out1_re;
  assign AddAfterFeedbackS_im = addtree_im_19 + Switch_out1_im;

  always @(posedge clk or posedge reset)
    begin : rt_bypass_process
      if (reset == 1'b1) begin
        rt_bypass_reg_re <= 16'sb0000000000000000;
        rt_bypass_reg_im <= 16'sb0000000000000000;
      end
      else begin
        if (enb_1_6_1) begin
          rt_bypass_reg_im <= AddAfterFeedbackS_im;
          rt_bypass_reg_re <= AddAfterFeedbackS_re;
        end
      end
    end

  assign Root_Raised_Cosine_Receive_Filter_out_re_1 = (enb_1_6_1 == 1'b1 ? AddAfterFeedbackS_re :
              rt_bypass_reg_re);
  assign Root_Raised_Cosine_Receive_Filter_out_im_1 = (enb_1_6_1 == 1'b1 ? AddAfterFeedbackS_im :
              rt_bypass_reg_im);

  assign Root_Raised_Cosine_Receive_Filter_out_re = Root_Raised_Cosine_Receive_Filter_out_re_1;

  assign Root_Raised_Cosine_Receive_Filter_out_im = Root_Raised_Cosine_Receive_Filter_out_im_1;

endmodule  // Root_Raised_Cosine_Receive_Filter

